 public function create(AuthenticatedRequestContext$c):Response{if(!$this->allowed($c))return new Response(403,'Forbidden');$properties=$this->service->properties();$months=$this->service->months();$input=$this->flash->pull('flyer_input',[]);$input=is_array($input)?$input:[];$candidateMonth=(string)($input['month']??'');$month=array_key_exists($candidateMonth,$months)?$candidateMonth:$this->service->currentMonth();$property=(string)($input['property']??'');$type=in_array(($input['type']??''),['standard','promo'],true)?(string)$input['type']:'standard';$user=$c->user;$csrfToken=$this->csrf->token();$error=(string)$this->flash->pull('flyer_error','');ob_start();require$this->views.'/corporate/marketing/flyers/form.php';return new Response(200,(string)ob_get_clean(),['Cache-Control'=>'private, no-store']);}
