 public function replaceForm(string$id,AuthenticatedRequestContext$c):Response{$flyer=$this->service->find($id);if(!$this->allowed($c))return new Response(403,'Forbidden');if(!$flyer)return new Response(404,'Not found');$user=$c->user;$csrfToken=$this->csrf->token();$error=$this->flash->pull('flyer_error','');ob_start();require$this->views.'/corporate/marketing/flyers/replace.php';return new Response(200,(string)ob_get_clean());}
 public function replace(Request$r,string$id,AuthenticatedRequestContext$c):Response{if(!$this->allowed($c))return new Response(403,'Forbidden');if(!$this->csrf->valid($r->post['_token']??null))return new Response(419,'Invalid request.');$flyer=$this->service->find($id);if(!$flyer)return new Response(404,'Not found');try{$result=$this->service->save($c->user,$flyer['property_public_id'],substr($flyer['flyer_month'],0,7),$flyer['flyer_type'],(array)($r->files['flyer']??[]),$id);$this->flash->put('flyer_success','Flyer replaced successfully. Manager notification queued for delivery.');if(($result['notification']['warning']??'')!=='')$this->flash->put('flyer_warning',$result['notification']['warning']);return Response::redirect($this->libraryRedirect($result['flyer']));}catch(\Throwable$e){$this->flash->put('flyer_error',$e instanceof \InvalidArgumentException?$e->getMessage():'The flyer could not be replaced safely.');return Response::redirect('/corporate/marketing/flyers/'.$id.'/replace');}}
